<?php
require __DIR__.'/config.php'; require_login();
$admin=($_SESSION['user']['role']??'')==='admin'; $page=$_GET['page']??'more'; $err='';
function mr(PDO $p,string $q,array $a=[]):array{$s=$p->prepare($q);$s->execute($a);return $s->fetchAll();}
function mi($n):string{return 'Rp '.number_format((float)$n,0,',','.');}
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$a=$_POST['action']??'';
try{
 if(in_array($a,['category','supplier','link','equipment','user','payment'],true)&&!$admin)throw new RuntimeException('403: tindakan ini hanya untuk admin.');
 if($a==='category'){$id=(int)($_POST['id']??0);$n=trim($_POST['name']??'');if(!$n)throw new RuntimeException('Nama kategori wajib.');if($id)$pdo->prepare('UPDATE categories SET name=?,description=? WHERE id=?')->execute([$n,trim($_POST['description']??''),$id]);else$pdo->prepare('INSERT INTO categories(name,description) VALUES(?,?)')->execute([$n,trim($_POST['description']??'')]);header('Location: manage.php?page=categories');exit;}
 if($a==='delete_category'){$pdo->prepare('DELETE FROM categories WHERE id=?')->execute([(int)$_POST['id']]);header('Location: manage.php?page=categories');exit;}
 if($a==='supplier'){$id=(int)($_POST['id']??0);$d=[trim($_POST['name']??''),trim($_POST['contact_name']??''),trim($_POST['phone']??''),trim($_POST['email']??'')];if(!$d[0]||!$d[2])throw new RuntimeException('Nama dan telepon pemasok wajib.');if($id){$d[]=$id;$pdo->prepare('UPDATE suppliers SET name=?,contact_name=?,phone=?,email=? WHERE id=?')->execute($d);}else$pdo->prepare('INSERT INTO suppliers(name,contact_name,phone,email) VALUES(?,?,?,?)')->execute($d);header('Location: manage.php?page=suppliers');exit;}
 if($a==='link'){$v=(float)($_POST['price']??-1);if($v<0)throw new RuntimeException('Harga tidak boleh negatif.');$pdo->prepare('INSERT INTO equipment_suppliers(equipment_id,supplier_id,supplier_price) VALUES(?,?,?) ON DUPLICATE KEY UPDATE supplier_price=VALUES(supplier_price)')->execute([(int)$_POST['equipment_id'],(int)$_POST['supplier_id'],$v]);header('Location: manage.php?page=suppliers');exit;}
 if($a==='equipment'){$id=(int)($_POST['id']??0);$d=[(int)$_POST['category_id'],trim($_POST['sku']??''),trim($_POST['brand']??''),trim($_POST['model']??''),(float)($_POST['daily_rate']??-1),(float)($_POST['deposit_amount']??0),trim($_POST['description']??'')];if(!$d[0]||!$d[1]||!$d[2]||!$d[3]||$d[4]<0||$d[5]<0)throw new RuntimeException('Lengkapi data. Tarif dan deposit tidak boleh negatif.');if($id){$d[]=$id;$pdo->prepare('UPDATE equipment SET category_id=?,sku=?,brand=?,model=?,daily_rate=?,deposit_amount=?,description=? WHERE id=?')->execute($d);}else{$sn=trim($_POST['serial_number']??'');if(!$sn)throw new RuntimeException('Nomor seri wajib.');$pdo->beginTransaction();$pdo->prepare('INSERT INTO equipment(category_id,sku,brand,model,daily_rate,deposit_amount,description) VALUES(?,?,?,?,?,?,?)')->execute($d);$eid=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO equipment_units(equipment_id,serial_number) VALUES(?,?)')->execute([$eid,$sn]);$pdo->commit();}header('Location: manage.php?page=equipment');exit;}
 if($a==='customer'){$id=(int)($_POST['id']??0);$d=[trim($_POST['name']??''),trim($_POST['phone']??''),trim($_POST['email']??'')?:null,trim($_POST['identity_number']??'')?:null,trim($_POST['address']??'')?:null];if(!$d[0]||!$d[1])throw new RuntimeException('Nama dan telepon wajib diisi.');if($id){$d[]=$id;$pdo->prepare('UPDATE customers SET name=?,phone=?,email=?,identity_number=?,address=? WHERE id=?')->execute($d);}else$pdo->prepare('INSERT INTO customers(name,phone,email,identity_number,address) VALUES(?,?,?,?,?)')->execute($d);header('Location: manage.php?page=customers');exit;}
 if($a==='user'){$name=trim($_POST['name']??'');$un=trim($_POST['username']??'');$pw=$_POST['password']??'';$role=$_POST['role']??'staff';if(!$name||!preg_match('/^[a-zA-Z0-9_.-]{3,60}$/',$un)||strlen($pw)<8||!in_array($role,['staff','admin'],true))throw new RuntimeException('Isi nama, username minimal 3 karakter, password minimal 8 karakter, dan role.');$pdo->prepare('INSERT INTO users(name,username,password_hash,role) VALUES(?,?,?,?)')->execute([$name,$un,password_hash($pw,PASSWORD_DEFAULT),$role]);header('Location: manage.php?page=users');exit;}
 if($a==='payment'){$amount=(float)($_POST['amount']??0);$type=$_POST['type']??'rental_fee';if($amount<=0||!in_array($type,['rental_fee','late_fee','refund'],true))throw new RuntimeException('Nominal harus positif dan jenis pembayaran valid.');$pdo->prepare('INSERT INTO payments(rental_id,received_by,payment_type,amount,method,note) VALUES(?,?,?,?,?,?)')->execute([(int)$_POST['rental_id'],$_SESSION['user']['id'],$type,$amount,$_POST['method']??'cash',trim($_POST['note']??'')]);header('Location: manage.php?page=payments');exit;}
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err=$e instanceof PDOException&&str_contains($e->getMessage(),'Duplicate')?'Data unik sudah digunakan.':$e->getMessage();}}
$cats=mr($pdo,'SELECT * FROM categories ORDER BY name');$equip=mr($pdo,'SELECT id,brand,model,sku FROM equipment ORDER BY brand,model');$sups=mr($pdo,'SELECT * FROM suppliers ORDER BY name');$rents=mr($pdo,'SELECT id,rental_code FROM rentals ORDER BY created_at DESC LIMIT 100');$edit=null;if(isset($_GET['edit'])){$table=match($page){'categories'=>'categories','suppliers'=>'suppliers','equipment'=>'equipment','customers'=>'customers',default=>''};if($table)$edit=mr($pdo,"SELECT * FROM $table WHERE id=? ",[(int)$_GET['edit']])[0]??null;}
$q=trim($_GET['q']??'');$cat=(int)($_GET['cat']??0);$status=$_GET['status']??'';$sort=$_GET['sort']??'brand';$dir=strtoupper($_GET['dir']??'ASC');$sorts=['brand'=>'e.brand','model'=>'e.model','sku'=>'e.sku','rate'=>'e.daily_rate','category'=>'c.name'];if(!isset($sorts[$sort]))$sort='brand';if(!in_array($dir,['ASC','DESC'],true))$dir='ASC';$where=[];$args=[];if($q!==''){$where[]='(e.brand LIKE ? OR e.model LIKE ? OR e.sku LIKE ? OR u.serial_number LIKE ?)';array_push($args,"%$q%","%$q%","%$q%","%$q%");}if($cat){$where[]='e.category_id=?';$args[]=$cat;}if(in_array($status,['available','rented','maintenance','retired'],true)){$where[]='u.status=?';$args[]=$status;}$ws=$where?'WHERE '.implode(' AND ',$where):'';$st=$pdo->prepare("SELECT COUNT(*) FROM equipment e JOIN categories c ON c.id=e.category_id LEFT JOIN equipment_units u ON u.equipment_id=e.id $ws");$st->execute($args);$total=(int)$st->fetchColumn();$per=10;$pages=max(1,(int)ceil($total/$per));$p=min($pages,max(1,(int)($_GET['p']??1)));$items=mr($pdo,"SELECT e.*,c.name category,u.serial_number,u.status FROM equipment e JOIN categories c ON c.id=e.category_id LEFT JOIN equipment_units u ON u.equipment_id=e.id $ws ORDER BY {$sorts[$sort]} $dir,u.serial_number LIMIT $per OFFSET ".(($p-1)*$per),$args);
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fitur Mini Project · Rental Camera</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="app-shell"><aside class="sidebar"><a class="logo" href="index.php"><span class="brand-mark small">RC</span><span>Rental Camera</span></a><div class="side-label">FITUR MINI PROJECT</div><?php foreach(['more'=>'Menu tambahan','equipment'=>'Cari peralatan','categories'=>'Kategori','customers'=>'Pelanggan','suppliers'=>'Pemasok','reports'=>'Laporan','payments'=>'Pembayaran'] as $k=>$v):?><a class="nav-item <?=$page===$k?'active':''?>" href="manage.php?page=<?=$k?>"><span>•</span><span><?=$v?></span></a><?php endforeach;?><?php if($admin):?><a class="nav-item <?=$page==='users'?'active':''?>" href="manage.php?page=users">⚙ <span>Pengguna</span></a><?php endif;?><a class="nav-item" href="index.php">← <span>Kembali</span></a></aside><main class="main"><header class="topbar">Rental Camera / Fitur tambahan <span><?=h($_SESSION['user']['name'])?> · <?=h($_SESSION['user']['role'])?></span></header><section class="content"><?php if($err):?><div class="alert"><?=h($err)?></div><?php endif;?>
<?php if($page==='more'):?><div class="page-heading"><div><p class="eyebrow">FITUR TUGAS</p><h1>Pengelolaan tambahan</h1><p>Pilih fitur yang ingin dikelola.</p></div></div><div class="stat-grid"><?php foreach(['equipment'=>'Pencarian, filter, sorting, pagination','categories'=>'CRUD kategori','suppliers'=>'Pemasok dan relasi M:N','users'=>'Role admin/staff','reports'=>'Dashboard laporan agregat','payments'=>'Pembayaran dan denda'] as $k=>$v):if($k==='users'&&!$admin)continue;?><a class="stat-card" href="manage.php?page=<?=$k?>"><span class="stat-title">Buka</span><strong><?=$k?></strong><small><?=$v?></small></a><?php endforeach;?></div>
<?php elseif($page==='equipment'):?><div class="page-heading"><div><p class="eyebrow">KATALOG</p><h1>Cari peralatan</h1><p>Kolom sorting dibatasi allowlist; halaman berisi 10 unit.</p></div></div><form class="panel filter-form" method="get"><input type="hidden" name="page" value="equipment"><input name="q" placeholder="Cari merek, model, SKU, nomor seri" value="<?=h($q)?>"><select name="cat"><option value="0">Semua kategori</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$cat===$c['id']?'selected':''?>><?=h($c['name'])?></option><?php endforeach;?></select><select name="status"><option value="">Semua status</option><?php foreach(['available','rented','maintenance','retired'] as $s):?><option <?=$status===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><select name="sort"><?php foreach(array_keys($sorts) as $s):?><option <?=$sort===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><select name="dir"><option>ASC</option><option <?=$dir==='DESC'?'selected':''?>>DESC</option></select><button class="button">Terapkan</button></form><?php if($admin):?><div class="panel"><h2><?=($edit?'Ubah peralatan':'Tambah peralatan dan unit')?></h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="equipment"><input type="hidden" name="id" value="<?=h((string)($edit['id']??''))?>"><label>Kategori<select name="category_id"><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=($edit['category_id']??'')==$c['id']?'selected':''?>><?=h($c['name'])?></option><?php endforeach;?></select></label><label>SKU unik<input name="sku" value="<?=h($edit['sku']??'')?>" required></label><label>Merek<input name="brand" value="<?=h($edit['brand']??'')?>" required></label><label>Model<input name="model" value="<?=h($edit['model']??'')?>" required></label><label>Tarif per hari<input type="number" name="daily_rate" min="0" value="<?=h((string)($edit['daily_rate']??''))?>" required></label><label>Deposit<input type="number" name="deposit_amount" min="0" value="<?=h((string)($edit['deposit_amount']??0))?>"></label><?php if(!$edit):?><label>Nomor seri unit<input name="serial_number" required></label><?php endif;?><label class="full">Deskripsi<input name="description" value="<?=h($edit['description']??'')?>"></label><button class="button">Simpan</button></form></div><?php endif;?><div class="table-wrap"><table><thead><tr><th>SKU</th><th>PERALATAN</th><th>KATEGORI</th><th>SERI</th><th>TARIF/HARI</th><th>STATUS</th><?php if($admin):?><th>AKSI</th><?php endif;?></tr></thead><tbody><?php foreach($items as $x):?><tr><td><?=h($x['sku'])?></td><td><?=h($x['brand'].' '.$x['model'])?></td><td><?=h($x['category'])?></td><td><?=h($x['serial_number']??'—')?></td><td><?=mi($x['daily_rate'])?></td><td><?=h($x['status']??'tanpa unit')?></td><?php if($admin):?><td><a class="text-link" href="manage.php?page=equipment&edit=<?=$x['id']?>">Ubah</a></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><p class="pagination">Halaman <?=$p?>/<?=$pages?> (<?=$total?> hasil) <?php if($p>1):?><a class="text-link" href="<?=h('manage.php?'.http_build_query(array_merge($_GET,['p'=>$p-1])))?>">← Sebelumnya</a><?php endif;?> <?php if($p<$pages):?><a class="text-link" href="<?=h('manage.php?'.http_build_query(array_merge($_GET,['p'=>$p+1])))?>">Berikutnya →</a><?php endif;?></p>
<?php elseif($page==='categories'):if(!$admin){http_response_code(403);exit('403 Forbidden: staff tidak dapat mengelola kategori.');}?><div class="page-heading"><h1>Kategori kamera</h1></div><div class="panel"><form method="post" class="form-grid compact"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="category"><input type="hidden" name="id" value="<?=h((string)($edit['id']??''))?>"><label>Nama<input name="name" value="<?=h($edit['name']??'')?>" required></label><label>Deskripsi<input name="description" value="<?=h($edit['description']??'')?>"></label><button class="button">Simpan kategori</button></form></div><div class="table-wrap"><table><thead><tr><th>KATEGORI</th><th>DESKRIPSI</th><th>AKSI</th></tr></thead><tbody><?php foreach($cats as $c):?><tr><td><?=h($c['name'])?></td><td><?=h($c['description'])?></td><td><a class="text-link" href="manage.php?page=categories&edit=<?=$c['id']?>">Ubah</a><form class="inline-form" method="post" onsubmit="return confirm('Hapus kategori? Data yang dipakai produk tidak dapat dihapus.')"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete_category"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="small-button">Hapus</button></form></td></tr><?php endforeach;?></tbody></table></div>
<?php elseif($page==='customers'):$ce=$edit;$cr=mr($pdo,'SELECT * FROM customers ORDER BY name LIMIT 200');?><div class="page-heading"><h1>Pelanggan</h1><p>Tambah atau ubah data pelanggan rental.</p></div><div class="panel"><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="customer"><input type="hidden" name="id" value="<?=h((string)($ce['id']??''))?>"><label>Nama<input name="name" value="<?=h($ce['name']??'')?>" required></label><label>Telepon<input name="phone" value="<?=h($ce['phone']??'')?>" required></label><label>Email<input name="email" value="<?=h($ce['email']??'')?>"></label><label>Nomor identitas<input name="identity_number" value="<?=h($ce['identity_number']??'')?>"></label><label class="full">Alamat<input name="address" value="<?=h($ce['address']??'')?>"></label><button class="button">Simpan pelanggan</button></form></div><div class="table-wrap"><table><thead><tr><th>NAMA</th><th>TELEPON</th><th>EMAIL</th><th>AKSI</th></tr></thead><tbody><?php foreach($cr as $c):?><tr><td><?=h($c['name'])?></td><td><?=h($c['phone'])?></td><td><?=h($c['email'])?></td><td><a class="text-link" href="manage.php?page=customers&edit=<?=$c['id']?>">Ubah</a></td></tr><?php endforeach;?></tbody></table></div><?php elseif($page==='suppliers'):if(!$admin){http_response_code(403);exit('403 Forbidden: fitur khusus admin.');}$links=mr($pdo,'SELECT e.brand,e.model,e.sku,s.name supplier,es.supplier_price FROM equipment_suppliers es JOIN equipment e ON e.id=es.equipment_id JOIN suppliers s ON s.id=es.supplier_id ORDER BY e.brand,s.name');?><div class="page-heading"><h1>Pemasok dan relasi many-to-many</h1></div><div class="panel"><h2><?= $edit ? "Ubah pemasok" : "Tambah pemasok" ?></h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="supplier"><input type="hidden" name="id" value="<?=h((string)($edit['id']??''))?>"><label>Nama<input name="name" value="<?=h($edit['name']??'')?>" required></label><label>Kontak<input name="contact_name" value="<?=h($edit['contact_name']??'')?>"></label><label>Telepon<input name="phone" value="<?=h($edit['phone']??'')?>" required></label><label>Email<input name="email" value="<?=h($edit['email']??'')?>"></label><button class="button">Simpan pemasok</button></form></div><div class="panel"><h2>Hubungkan pemasok dengan peralatan</h2><form method="post" class="form-grid compact"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="link"><label>Peralatan<select name="equipment_id"><?php foreach($equip as $e):?><option value="<?=$e['id']?>"><?=h($e['brand'].' '.$e['model'].' '.$e['sku'])?></option><?php endforeach;?></select></label><label>Pemasok<select name="supplier_id"><?php foreach($sups as $s):?><option value="<?=$s['id']?>"><?=h($s['name'])?></option><?php endforeach;?></select></label><label>Harga pemasok<input type="number" min="0" name="price" value="0"></label><button class="button">Hubungkan</button></form></div><div class="table-wrap"><table><thead><tr><th>PERALATAN</th><th>SKU</th><th>PEMASOK</th><th>HARGA</th></tr></thead><tbody><?php foreach($links as $l):?><tr><td><?=h($l['brand'].' '.$l['model'])?></td><td><?=h($l['sku'])?></td><td><?=h($l['supplier'])?></td><td><?=mi($l['supplier_price'])?></td></tr><?php endforeach;?></tbody></table></div>
<?php elseif($page==='users'):if(!$admin){http_response_code(403);exit('403 Forbidden: staff dilarang mengelola akun.');}$us=mr($pdo,'SELECT id,name,username,role,created_at FROM users ORDER BY name');?><div class="page-heading"><h1>Akun admin dan staff</h1></div><div class="panel"><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="user"><label>Nama<input name="name" required></label><label>Username<input name="username" minlength="3" required></label><label>Password minimal 8 karakter<input type="password" name="password" minlength="8" required></label><label>Role<select name="role"><option value="staff">Staff</option><option value="admin">Admin</option></select></label><button class="button">Buat akun (password di-hash)</button></form></div><div class="table-wrap"><table><thead><tr><th>NAMA</th><th>USERNAME</th><th>ROLE</th></tr></thead><tbody><?php foreach($us as $u):?><tr><td><?=h($u['name'])?></td><td><?=h($u['username'])?></td><td><?=h($u['role'])?></td></tr><?php endforeach;?></tbody></table></div>
<?php elseif($page==='payments'):if(!$admin){http_response_code(403);exit('403 Forbidden: pembayaran admin.');}$pay=mr($pdo,'SELECT p.*,r.rental_code FROM payments p JOIN rentals r ON r.id=p.rental_id ORDER BY p.paid_at DESC LIMIT 100');?><div class="page-heading"><h1>Pembayaran dan denda</h1></div><div class="panel"><form method="post" class="form-grid compact"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="payment"><label>Transaksi<select name="rental_id"><?php foreach($rents as $r):?><option value="<?=$r['id']?>"><?=h($r['rental_code'])?></option><?php endforeach;?></select></label><label>Jenis<select name="type"><option value="rental_fee">Biaya sewa</option><option value="late_fee">Denda</option><option value="refund">Refund</option></select></label><label>Nominal<input type="number" min="1" name="amount" required></label><label>Metode<select name="method"><option>cash</option><option>transfer</option><option>card</option><option>other</option></select></label><button class="button">Simpan pembayaran</button></form></div><div class="table-wrap"><table><thead><tr><th>WAKTU</th><th>SEWA</th><th>JENIS</th><th>NOMINAL</th><th>METODE</th></tr></thead><tbody><?php foreach($pay as $x):?><tr><td><?=h($x['paid_at'])?></td><td><?=h($x['rental_code'])?></td><td><?=h($x['payment_type'])?></td><td><?=mi($x['amount'])?></td><td><?=h($x['method'])?></td></tr><?php endforeach;?></tbody></table></div>
<?php elseif($page==='reports'):$report=mr($pdo,"SELECT c.name,COUNT(DISTINCT e.id) models,COUNT(u.id) units,COALESCE(SUM(u.status='available'),0) available,COALESCE(SUM(u.status='rented'),0) rented,COALESCE(SUM(u.status='maintenance'),0) maintenance FROM categories c LEFT JOIN equipment e ON e.category_id=c.id LEFT JOIN equipment_units u ON u.equipment_id=e.id GROUP BY c.id,c.name ORDER BY c.name");$rev=(float)$pdo->query("SELECT COALESCE(SUM(amount),0) FROM payments WHERE payment_type IN ('rental_fee','late_fee')")->fetchColumn();?><div class="page-heading"><h1>Laporan rental</h1><p>Ringkasan kategori dan agregat pembayaran.</p></div><div class="stat-grid"><article class="stat-card"><span class="stat-title">Pendapatan sewa + denda</span><strong><?=mi($rev)?></strong><small>SUM pembayaran</small></article><article class="stat-card"><span class="stat-title">Total unit</span><strong><?=(int)$pdo->query('SELECT COUNT(*) FROM equipment_units')->fetchColumn()?></strong><small>COUNT unit</small></article></div><div class="table-wrap"><table><thead><tr><th>KATEGORI</th><th>MODEL</th><th>UNIT</th><th>TERSEDIA</th><th>DISEWA</th><th>PERAWATAN</th></tr></thead><tbody><?php foreach($report as $r):?><tr><td><?=h($r['name'])?></td><td><?=$r['models']?></td><td><?=$r['units']?></td><td><?=$r['available']?></td><td><?=$r['rented']?></td><td><?=$r['maintenance']?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></main></div></body></html>
